  if isinstance(n,ast.Call) and isinstance(n.func,ast.Name):assert n.func.id not in {'open','exec','eval','__import__','input'}
 # Normalize only docstring, CONFIG and the three switch defaults for cross-source identity.
 a.body[0].value.value='NORMALIZED'
 next(n for n in a.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets)).value=ast.Constant(None)
 for arg,v in zip(init.args.args[-len(init.args.defaults):],init.args.defaults):
  if arg.arg in {'residual_routing','action_in_pool','action_in_summaries'}:v.value='NORMALIZED'
 canonical.append(ast.dump(a))
